const grouped = {};
const seen = new Set();

for (const item of $input.all()) {

  const event = item.json;

  if (!event.start?.dateTime || !event.end?.dateTime) continue;

  const date = event.start.dateTime.slice(0,10);
  const start = event.start.dateTime.slice(11,16);
  const end = event.end.dateTime.slice(11,16);
  const summary = event.summary || "";

  const key = `${date}_${start}_${end}_${summary}`;

  // skip duplicates
  if (seen.has(key)) continue;
  seen.add(key);

  if (!grouped[date]) {
    grouped[date] = [];
  }

  grouped[date].push({
    start,
    end,
    summary
  });
}

// sort days and events
return Object.keys(grouped)
.sort()
.map(date => ({
  json: {
    date,
    events: grouped[date].sort((a,b)=>a.start.localeCompare(b.start))
  }
}));

// ==========================================
// CONFIG
// ==========================================
const OFFSET = "-03:00";
const TIMEZONE = "America/Argentina/Buenos_Aires";

const CONFIG = {
  APERTURA: "08:00",
  CIERRE: "18:00",
  INICIO_ALMUERZO: "12:00",
  FIN_ALMUERZO: "13:00",
  TIEMPO_RECEPCION: 15,
  TIEMPO_LAVADO: 30,
  TIEMPO_PREPARACION: 15,
  MIN_HORAS_TURNO: 18,
  DIAS_LABORALES: [1,2,3,4,5],
  MAX_DIAS_BUSQUEDA: 60
};

// ==========================================
// TIEMPO SERVICIO
// ==========================================
const tiempoNode = $('get_tiempos1').first().json;

let TIEMPO_SERVICIO = 45;

if (tiempoNode?.tiempo) {
  if (typeof tiempoNode.tiempo === "string" && tiempoNode.tiempo.includes(":")) {
    const [h, m] = tiempoNode.tiempo.split(":").map(Number);
    TIEMPO_SERVICIO = h * 60 + m;
  } else {
    TIEMPO_SERVICIO = parseInt(tiempoNode.tiempo) || 45;
  }
}

// ==========================================
// EVENTOS GOOGLE CALENDAR
// ==========================================
const eventosPorDia = {};

for (const item of $input.all()) {
  const fecha = item.json.date;
  const eventos = item.json.events || [];

  eventosPorDia[fecha] = eventos.map(e => {
    let inicio, fin;
    if (e.start?.dateTime) {
      inicio = new Date(e.start.dateTime);
      fin = new Date(e.end.dateTime);
    } else {
      inicio = new Date(`${fecha}T${e.start}:00${OFFSET}`);
      fin = new Date(`${fecha}T${e.end}:00${OFFSET}`);
    }
    return { inicio, fin };
  }).filter(e => e.inicio && e.fin);
}

// ==========================================
// HELPERS
// ==========================================
function timeToMinutes(t) {
  const [h, m] = t.split(":").map(Number);
  return h * 60 + m;
}

function minutesToTime(min) {
  const h = Math.floor(min / 60);
  const m = min % 60;
  return `${h.toString().padStart(2,'0')}:${m.toString().padStart(2,'0')}`;
}

function formatoFechaCompleta(fechaStr) {
  const dias = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
  const f = new Date(fechaStr + "T00:00:00" + OFFSET);
  return `${dias[f.getDay()]} ${f.toLocaleDateString("es-AR")}`;
}

// ==========================================
// HORARIOS BASE
// ==========================================
const apertura    = timeToMinutes(CONFIG.APERTURA);
const cierre      = timeToMinutes(CONFIG.CIERRE);
const almuerzoIni = timeToMinutes(CONFIG.INICIO_ALMUERZO);
const almuerzoFin = timeToMinutes(CONFIG.FIN_ALMUERZO);

// ==========================================
// BUSQUEDA
// ==========================================
const ahora = new Date();
const fechaMinima = new Date(ahora.getTime() + CONFIG.MIN_HORAS_TURNO * 3600000);

// Busca el primer slot libre a partir de `desde` hasta `hasta`
function buscarDesde(fechaStr, desde, hasta, eventos) {
  for (let hora = desde; hora + TIEMPO_SERVICIO <= hasta; hora += 15) {
    const inicioDate = new Date(`${fechaStr}T${minutesToTime(hora)}:00${OFFSET}`);
    if (inicioDate < fechaMinima) continue;

    // No arrancar en almuerzo
    if (hora >= almuerzoIni && hora < almuerzoFin) continue;

    // No terminar pasando el cierre
    if (hora + TIEMPO_SERVICIO > cierre) continue;

    // Verificar contra eventos (solo TIEMPO_SERVICIO, sin extras)
    const recepcion = new Date(`${fechaStr}T${minutesToTime(hora - CONFIG.TIEMPO_RECEPCION)}:00${OFFSET}`);
    const finServicio = new Date(`${fechaStr}T${minutesToTime(hora + TIEMPO_SERVICIO)}:00${OFFSET}`);
    const libre = !eventos.some(e => recepcion < e.fin && finServicio > e.inicio);

    if (libre) return hora;
  }
  return null;
}

function construirTurno(fechaStr, hora) {
  const finServicio = hora + TIEMPO_SERVICIO;
  const llegada = hora - CONFIG.TIEMPO_RECEPCION;

  // Entrega = fin servicio + lavado + preparacion, saltando almuerzo si aplica
  let entrega = finServicio + CONFIG.TIEMPO_LAVADO + CONFIG.TIEMPO_PREPARACION;
  if (finServicio <= almuerzoIni && entrega > almuerzoIni) {
    entrega += (almuerzoFin - almuerzoIni);
  }

  return {
    dia: fechaStr,
    inicio: minutesToTime(hora),
    final: minutesToTime(finServicio),
    horarioLlegada: minutesToTime(llegada),
    horarioEntrega: minutesToTime(entrega),
    fechaFormato: formatoFechaCompleta(fechaStr),
    Id_Calendario: "a53b69d6815a2d4305369311426ce3576383afa505d99095c577f9646361a062@group.calendar.google.com"
  };
}

// Franjas horarias para rotar y dar variedad
const FRANJAS = [
  { desde: timeToMinutes("08:00"), hasta: timeToMinutes("10:00") },
  { desde: timeToMinutes("10:00"), hasta: timeToMinutes("12:00") },
  { desde: timeToMinutes("13:00"), hasta: timeToMinutes("15:30") },
  { desde: timeToMinutes("15:30"), hasta: timeToMinutes("18:00") },
];

let turnosDisponibles = [];
let fecha = new Date();
fecha.setDate(fecha.getDate() + 1);
let dias = 0;
let franjaIdx = 0;

while (turnosDisponibles.length < 4 && dias < CONFIG.MAX_DIAS_BUSQUEDA) {

  const fechaStr = fecha.toLocaleDateString("en-CA", { timeZone: TIMEZONE });
  const diaSemana = fecha.getDay();

  if (CONFIG.DIAS_LABORALES.includes(diaSemana)) {
    const eventos = eventosPorDia[fechaStr] || [];

    // Intentar encontrar en la franja actual, si no hay, probar las demás
    let encontrado = false;
    for (let intento = 0; intento < FRANJAS.length; intento++) {
      const franja = FRANJAS[(franjaIdx + intento) % FRANJAS.length];
      const slot = buscarDesde(fechaStr, franja.desde, franja.hasta, eventos);
      if (slot !== null) {
        turnosDisponibles.push(construirTurno(fechaStr, slot));
        franjaIdx = (franjaIdx + intento + 1) % FRANJAS.length; // avanzar franja para el próximo
        encontrado = true;
        break;
      }
    }
  }

  fecha.setDate(fecha.getDate() + 1);
  dias++;
}

// ==========================================
// ORDEN FINAL
// ==========================================
turnosDisponibles.sort((a, b) =>
  a.dia === b.dia
    ? a.inicio.localeCompare(b.inicio)
    : new Date(a.dia) - new Date(b.dig)
);

// ==========================================
// OUTPUT
// ==========================================
return [{
  json: {
    turnosDisponibles: turnosDisponibles.slice(0, 4),
    tiempoServicio: TIEMPO_SERVICIO,
    cantidad: turnosDisponibles.length
  }
}];
